import{_ as a,o as d,c as e,a3 as S}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"CSS 方案选型","description":"","frontmatter":{"title":"CSS 方案选型","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/ui/css-strategy.md","filePath":"frontend/decisions/ui/css-strategy.md","lastUpdated":1785589115000}'),r={name:"frontend/decisions/ui/css-strategy.md"};function i(o,t,l,s,h,c){return d(),e("div",null,[...t[0]||(t[0]=[S('<h1 id="css-方案选型" tabindex="-1">CSS 方案选型 <a class="header-anchor" href="#css-方案选型" aria-label="Permalink to &quot;CSS 方案选型&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>CSS 方案决定样式如何隔离、复用、组合、按需产出和随组件演进。全局 CSS、命名约定、CSS Modules、Vue Scoped CSS、原子化 CSS 和 CSS-in-JS 解决的维度并不完全相同，实际方案可以组合，但必须明确每一层负责什么。</p><p>具体工具用法参见专题进阶的<a href="/frontend/topics/css-solutions/architecture">CSS 方案与工具</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>样式问题通常来自三类冲突：选择器互相影响、视觉值难以统一、组件变体不断复制。只用一种工具很难同时解决作用域、设计令牌和布局复用；同时堆叠 Sass、Scoped、CSS-in-JS 和原子类又会让规则不可预测。</p><p>决策应分别说明作用域、令牌、组件变体、全局基础样式和运行时动态值的责任。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>支持目标浏览器、SSR/SSG 和 CSP；</li><li>样式顺序在开发与生产构建中可预测；</li><li>关键组件满足无障碍的缩放、对比度和用户样式要求；</li><li>组件卸载、异步加载和多应用组合不会残留错误样式；</li><li>设计令牌可被需要的产品和技术栈消费。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较作用域隔离、静态提取、运行时成本、动态能力、共置、调试、类型和编辑器支持、设计令牌、跨框架共享、学习成本、构建依赖和迁移成本。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-全局-css-与命名约定" tabindex="-1">3.1 全局 CSS 与命名约定 <a class="header-anchor" href="#_3-1-全局-css-与命名约定" aria-label="Permalink to &quot;3.1 全局 CSS 与命名约定&quot;">​</a></h3><p>BEM、ITCSS 等约定通过命名和分层控制冲突，运行时和构建依赖低，适合内容站或已有成熟规范。隔离依赖人工和检查，组件删除时容易留下无主样式。</p><h3 id="_3-2-css-modules-或-scoped-css" tabindex="-1">3.2 CSS Modules 或 Scoped CSS <a class="header-anchor" href="#_3-2-css-modules-或-scoped-css" aria-label="Permalink to &quot;3.2 CSS Modules 或 Scoped CSS&quot;">​</a></h3><p>构建时为类名或选择器建立局部作用域，适合组件化应用。它保留标准 CSS 和静态提取，但全局主题、穿透子组件和动态类组合仍需明确规则。Vue 项目通常可用 SFC <code>scoped</code>，跨框架库可优先 CSS Modules 或明确前缀。</p><h3 id="_3-3-原子化-css" tabindex="-1">3.3 原子化 CSS <a class="header-anchor" href="#_3-3-原子化-css" aria-label="Permalink to &quot;3.3 原子化 CSS&quot;">​</a></h3><p>通过受控工具类直接组合布局和视觉值，能减少命名与重复，并通过约束配置保持一致。模板类名会更密集，复杂组件状态和跨团队任意值需要治理；动态拼接类名还会影响扫描和产物生成。</p><h3 id="_3-4-css-in-js" tabindex="-1">3.4 CSS-in-JS <a class="header-anchor" href="#_3-4-css-in-js" aria-label="Permalink to &quot;3.4 CSS-in-JS&quot;">​</a></h3><p>在 JavaScript/TypeScript 中描述样式，可深度结合组件状态、主题和类型。不同实现可能运行时注入或构建时提取，性能、SSR、CSP 和框架绑定必须按具体库验证，不能一概而论。</p><h3 id="_3-5-组合策略" tabindex="-1">3.5 组合策略 <a class="header-anchor" href="#_3-5-组合策略" aria-label="Permalink to &quot;3.5 组合策略&quot;">​</a></h3><p>常见组合是全局基础层与令牌、组件局部样式、少量原子工具。组合必须规定优先级和例外，否则同一属性会在多个体系中争夺控制权。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>全局命名</th><th>Modules / Scoped</th><th>原子化</th><th>CSS-in-JS</th></tr></thead><tbody><tr><td>局部隔离</td><td>依赖约定</td><td>强</td><td>类规则全局但组合局部</td><td>依实现通常较强</td></tr><tr><td>静态 CSS</td><td>是</td><td>是</td><td>是</td><td>取决于实现</td></tr><tr><td>运行时成本</td><td>无</td><td>无</td><td>无</td><td>可能存在</td></tr><tr><td>动态状态</td><td>CSS 类/变量</td><td>CSS 类/变量</td><td>条件类</td><td>与 JS 结合强</td></tr><tr><td>跨框架共享</td><td>CSS 易共享</td><td>需构建约定</td><td>配置和类名可共享</td><td>通常框架绑定较强</td></tr><tr><td>CSP/SSR 风险</td><td>低</td><td>低</td><td>低</td><td>需验证注入与顺序</td></tr><tr><td>团队治理</td><td>命名规则</td><td>作用域和穿透规则</td><td>令牌与任意值规则</td><td>库、缓存和注入规则</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例是 Vue 3 企业后台，30 名开发者、一个设计系统、需要 SSR 的客户门户共享部分组件；已有大量 Sass，但嵌套和全局选择器导致冲突。CSP 不允许无 nonce 的运行时样式注入。</p><p>推荐方案：</p><ul><li>全局只保留 reset、字体、设计令牌和低层级主题规则；</li><li>Vue 应用组件使用 SFC Scoped CSS，跨框架组件使用带前缀的静态 CSS；</li><li>Sass 仅用于当前 CSS 尚不能清楚表达的构建时组织，不允许深层嵌套；</li><li>提供有限的布局原子类，不开放任意颜色和尺寸；</li><li>动态值通过类和 CSS 自定义属性传递，不采用运行时 CSS-in-JS。</li></ul><p>该结论来自现有 Vue 资产、静态提取和 CSP 约束，不代表 CSS-in-JS 在其他项目中不合适。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>局部样式降低命名冲突，令牌保持跨应用一致。团队需要处理 Scoped 的选择器穿透、门户和 Teleport 内容、第三方组件覆盖，以及全局层的审查。</p><p>短期会存在旧全局 Sass 与新方案双轨，应以页面迁移为单位删除旧选择器，并通过视觉回归防止顺序变化。退出 Scoped 或 Modules 时，标准 CSS 仍可迁移；大量工具专属语法会提高成本。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>简单文档站不必引入运行时 CSS 方案。</li><li>不要用 <code>!important</code> 和深层穿透弥补组件 API 缺失。</li><li>原子类和 Scoped CSS 同时使用时，应规定谁负责布局和视觉变体。</li><li>Sass 嵌套不会自动形成组件作用域。</li><li>CSS-in-JS 必须按具体实现验证静态提取、SSR 和 CSP，不能只看类型体验。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>Vue 后台与 SSR 门户如何组织和隔离样式</td></tr><tr><td>硬约束</td><td>静态提取；CSP；设计令牌共享；无障碍；旧 Sass 可渐进迁移</td></tr><tr><td>候选</td><td>全局 BEM、Scoped/Modules、原子化、CSS-in-JS、组合</td></tr><tr><td>决定</td><td>全局基础 + Scoped/静态组件 CSS + 有限原子类</td></tr><tr><td>接受代价</td><td>多层职责规范；处理 Teleport 和第三方覆盖</td></tr><tr><td>明确不做</td><td>运行时 CSS-in-JS；开放任意设计值；新增深层全局 Sass</td></tr><tr><td>验证指标</td><td>样式冲突缺陷、未使用 CSS、视觉回归、CSP 违规、构建 CSS 体积</td></tr><tr><td>退出路径</td><td>标准 CSS 和自定义属性；令牌独立发布</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>跨框架组件占比显著增长、运行时主题需求无法由 CSS 变量满足、CSS 体积持续超预算、Scoped 穿透成为主要维护成本，或 CSP 与 SSR 约束变化时复查。局部组件难写不应触发全局方案更换，应先检查组件边界。</p>',39)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
